+
+function buildSchemaRejection(toolName: string, validationErrors: ErrorObject[]): ToolResponse {
+  const failures = validationErrors.map(describeValidationError);
+  log.warn('tool', 'input validation failed', {
+    name: toolName,
+    failures: failures.map(({path, constraint}) => ({path, constraint})),
