    const missingProperty = String(validationError.params.missingProperty);
    const path = [basePath, missingProperty].filter(Boolean).join('.');
    return {path, constraint: 'required', summary: `${path} is required`};
  }
  const targetPath = basePath || '<root>';
  if (validationError.keyword === 'type') {
    const expectedType = String(validationError.params.type);
    return {
      path: targetPath,
      constraint: `type: ${expectedType}`,
      summary: `${targetPath} must be of type ${expectedType}`,
    };
  }
  return {
    path: targetPath,
    constraint: validationError.keyword,
    summary: `${targetPath} failed ${validationError.keyword} constraint`,
  };
}

